-- Reabertura seletiva autorizada: 938 resultados pontuais + 3537 buscas.
-- A fila antiga conserva sua ordem. Builds e publicacoes existentes permanecem.
begin;
set local statement_timeout='180s';
set local lock_timeout='10s';
do $correcao$
declare
 v_lote uuid:=gen_random_uuid(); v_lote_anterior uuid:=gen_random_uuid();
 v_formula constant text:='a1cc830af3366e2d0c9ac12138d892058b3e57ed216e43d68242d105b33cb9d2';
 v_motor constant text:='otimizador-fila-producao-v3-local-20260909-habilidades-v12';
 v_regua jsonb; v_contrato text; v_agora timestamptz:=clock_timestamp();
 v_ordem_antes text; v_ordem_depois text; v_pub_antes text; v_pub_depois text;
 v_total_pub bigint; v_n bigint;
begin
 if exists(select 1 from clube_novo.otimizador_evento_producao_v3 where detalhe->>'contrato'='correcao_habilidades_0909_v12') then raise exception 'Correcao ja preparada; nao duplicar'; end if;
 create temp table _ids_hab(linha_id bigint primary key, build_anterior bigint, rapida boolean) on commit drop;
 perform 1 from clube_novo.build_linha_card l join _ids_hab a on a.linha_id=l.id for update of l;
 if (select count(*) from clube_novo.build_linha_card l join _ids_hab a on a.linha_id=l.id where l.estado='pendente' and l.estado_otimizador='concluido' and l.execucao_tipo='producao' and l.build_otimizador_id=a.build_anterior)<>4475 then raise exception 'Alvos mudaram desde a auditoria'; end if;
 if exists(select 1 from clube_novo.orcamento_revisao_linha_v1 r join _ids_hab a on a.linha_id=r.linha_anterior_id) then raise exception 'Antecessor substituido indevido'; end if;
 if exists(select 1 from clube_novo.otimizador_lote_producao_linha_v3 q join _ids_hab a using(linha_id) where q.reserva_token is not null or q.worker_id is not null or q.reservada_em is not null) then raise exception 'Alvo reservado'; end if;
 if exists(select 1 from clube_novo.otimizador_lote_producao_v3 t where t.id in(select q.lote_id from clube_novo.otimizador_lote_producao_linha_v3 q join _ids_hab a using(linha_id)) and t.estado not in('pausado','concluido')) then raise exception 'Lote de origem ativo'; end if;
 select md5(string_agg(to_jsonb(q)::text,'|' order by q.lote_id,q.ordem_fila,q.linha_id)) into v_ordem_antes from clube_novo.otimizador_lote_producao_linha_v3 q where not exists(select 1 from _ids_hab a where a.linha_id=q.linha_id);
 select count(*) into v_total_pub from clube_novo.build_publicacao_linha_ativa_v1;
 select md5(string_agg(to_jsonb(p)::text,'|' order by p.linha_id)) into v_pub_antes from clube_novo.build_publicacao_linha_ativa_v1 p join _ids_hab a using(linha_id);
 select public.otimizador_regua_v2() into v_regua;
 v_contrato:=clube_novo.otimizador_producao_contrato_fingerprint_v3(v_regua);
 if not coalesce((v_regua#>>'{gate,pode_rodar}')::boolean,false) or v_regua#>>'{politica_habilidades,versao}' is distinct from 'habilidades-funcao-20260909-v1' or jsonb_array_length(v_regua->'bloqueios')<>325 then raise exception 'Regua fora da politica aprovada'; end if;
 create temp table _cartas_hab on commit drop as
 select c.card_id,c.overall,public.otimizador_carta_v3(c.card_id) entrada,
 c.extraido_em::text carta_versao,clube_novo.bonificador_carta_fingerprint_v1(c.card_id) carta_fp,
 p.orcamento_real,p.prioridade_grupo
 from clube_novo.carta_jogo c left join clube_novo.otimizador_prioridade_orcamento_v1 p using(card_id)
 where c.card_id in(select l.card_id from clube_novo.build_linha_card l join _ids_hab a on a.linha_id=l.id);
 if (select count(*) from _cartas_hab)<>772 or exists(select 1 from _cartas_hab where not coalesce((entrada#>>'{gate,pode_rodar}')::boolean,false) or prioridade_grupo is null or (entrada#>>'{escalares,orcamento}')::int is distinct from orcamento_real or carta_versao is null or carta_fp is null) then raise exception 'Entrada ou orcamento sem confirmacao'; end if;
 create temp table _alvo_hab on commit drop as
 select a.*,case when row_number() over(partition by l.card_id,l.funcao_id,l.posicao_id,l.impeto_condicional_codigo,l.impeto_condicional_nivel order by l.id desc)=1 then v_lote else v_lote_anterior end lote_novo,l.card_id,c.overall,c.entrada,c.carta_versao,c.carta_fp,
 encode(extensions.digest(convert_to(c.entrada::text,'UTF8'),'sha256'),'hex') entrada_fp,
 to_jsonb(l) linha_antes,to_jsonb(q) fila_antes,
 (select to_jsonb(p) from clube_novo.build_publicacao_linha_ativa_v1 p where p.linha_id=l.id) publicacao_antes,
 (select to_jsonb(d) from clube_novo.build_pontuacao_final_v2_delta_v1 d where d.linha_id=l.id) delta_antes,
 (select to_jsonb(f) from clube_novo.build_finalizacao_fila_v1 f where f.linha_id=l.id) finalizacao_antes
 from _ids_hab a join clube_novo.build_linha_card l on l.id=a.linha_id join _cartas_hab c using(card_id)
 left join clube_novo.otimizador_lote_producao_linha_v3 q on q.linha_id=l.id;
 if (select count(*) from _alvo_hab)<>4475 then raise exception 'Duplicacao de alvos'; end if;
 select lote_novo,'otimizador_fila_producao_v3','integral','pausado',v_formula,v_contrato,v_motor,v_regua,encode(extensions.digest(convert_to(lote_novo::text||v_contrato,'UTF8'),'sha256'),'hex'),count(distinct card_id),count(*),0,0,0,false,count(distinct card_id),count(distinct card_id),encode(extensions.digest(convert_to(lote_novo::text||v_contrato,'UTF8'),'sha256'),'hex'),v_agora,v_agora from _alvo_hab group by lote_novo;
 select distinct lote_novo,card_id,overall,entrada,'otimizador_entradas_v3',entrada_fp,carta_versao,carta_fp from _alvo_hab;
 select lote_novo,'lote_criado',jsonb_build_object('contrato','correcao_habilidades_0909_v12','ordem_prefixo',case when lote_novo=v_lote then 1 else 2 end,'linhas',count(*),'cartas',count(distinct card_id),'rapidas',count(*) filter(where rapida),'motor',count(*) filter(where not rapida),'ancestrais_ja_substituidas',28,'aguardam_orcamento',6,'fila_anterior_md5',v_ordem_antes,'publicacoes_preservadas',v_total_pub,'worker_iniciado',false) from _alvo_hab group by lote_novo;
 select lote_novo,linha_id,'preparo_fatia_concluida',jsonb_build_object('contrato','arquivo_linha_antes_habilidades_0909_v12','correcao_rapida',rapida,'build_anterior',build_anterior,'linha_antes',linha_antes,'fila_antes',fila_antes,'publicacao_ativa_antes',publicacao_antes,'delta_publico_antes',delta_antes,'finalizacao_antes',finalizacao_antes) from _alvo_hab;
 delete from clube_novo.otimizador_lote_producao_linha_v3 q using _alvo_hab a where q.linha_id=a.linha_id;
 get diagnostics v_n=row_count;
 if v_n<>4365 then raise exception 'Fila de origem mudou: %',v_n; end if;
 update clube_novo.build_linha_card l set
 lote_producao_id=a.lote_novo,build_otimizador_id=null,estado_otimizador='pendente',erro_otimizador=null,
 otimizador_iniciado_em=null,otimizador_finalizado_em=null,lote_estado='pausado',lote_estado_atualizado_em=v_agora,lote_falha=null,
 otimizador_formula_fingerprint_esperado=v_formula,otimizador_contrato_fingerprint_esperado=v_contrato,otimizador_motor_versao_esperada=v_motor,
 snapshot_otimizador_fingerprint=null,otimizador_motor_versao=null,otimizador_contrato_versao=null,
 nota_otimizador_resultado_fingerprint=null,atributos_snapshot=null,atributos_snapshot_fingerprint=null
 from _alvo_hab a where l.id=a.linha_id;
 get diagnostics v_n=row_count;
 if v_n<>4475 then raise exception 'Quantidade reaberta divergente'; end if;
 -- B e seus selos continuam na linha; O anterior e publicacao continuam no historico.
 select lote_novo,linha_id,card_id,row_number() over(partition by lote_novo order by linha_id),overall,entrada_fp,null,null,null,null,0,null from _alvo_hab;
 update clube_novo.otimizador_lote_producao_v3 t set linhas=(select count(*) from clube_novo.otimizador_lote_producao_linha_v3 q where q.lote_id=t.id),atualizado_em=v_agora where t.id in(select distinct (fila_antes->>'lote_id')::uuid from _alvo_hab where fila_antes is not null);
 select md5(string_agg(to_jsonb(q)::text,'|' order by q.lote_id,q.ordem_fila,q.linha_id)) into v_ordem_depois from clube_novo.otimizador_lote_producao_linha_v3 q where not exists(select 1 from _ids_hab a where a.linha_id=q.linha_id);
 select md5(string_agg(to_jsonb(p)::text,'|' order by p.linha_id)) into v_pub_depois from clube_novo.build_publicacao_linha_ativa_v1 p join _ids_hab a using(linha_id);
 if v_ordem_antes is distinct from v_ordem_depois then raise exception 'Fila anterior foi alterada'; end if;
 if v_pub_antes is distinct from v_pub_depois or (select count(*) from clube_novo.build_publicacao_linha_ativa_v1)<>v_total_pub then raise exception 'Publicacao anterior foi alterada'; end if;
 if exists(select 1 from clube_novo.build_linha_card l join _alvo_hab a on a.linha_id=l.id where l.estado_otimizador<>'pendente' or l.build_otimizador_id is not null or l.build_bonificador_id is distinct from (a.linha_antes->>'build_bonificador_id')::bigint) then raise exception 'Reabertura ou preservacao B falhou'; end if;
end $correcao$;
commit;
